        Assert.Equal(captura.Respuesta.Encabezado("X-Correlation-Id"), captura.Respuesta.Json.GetProperty("traceId").GetString());
    }

    [Theory]
    [MemberData(nameof(Codigos))]
    [Trait("CA", "CA-07")]
